namespace StrataLint.Scribe.Blueprint.D5.S3.Combinatorics.Turnpike;

internal sealed class PrunedSingletonProjectionObstructionDocument : IScribeDocumentDefinition
{
    private const string Module = "D5/S3/Combinatorics/Turnpike/PrunedSingletonProjectionObstruction";
    private static LibraryNoteRef Source => LibraryNoteRef.Create("D5/L/FiniteGeometry/elder2026turnpike");
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "A realizable nine-point input refutes sufficiency of every singleton-pair cut for the pruned spine projection.",
        H("Singleton cuts do not complete the pruned spine projection"),
        Blocks(
            Paragraph(Text("The complete guarded numerical addition relation and the three triangle marginals follow Elder, Marçais and Kingsford, WABI 2026, Proposition 10 and System 11; see also Section 5. Source DOI: 10.4230/LIPIcs.WABI.2026.20, licensed CC BY 4.0. The exact rank-pruned all-singleton-cut projection comparison and the nine-point construction are repository-derived. This is an internal finite-instance refutation, with no external named-conjecture, priority, minimum-size or algorithmic-performance assertion.")),
            Paragraph(Text("Publication indices are one-based; Lean indices subtract one. I is every interval ij with 1≤i<j≤n, Delta every triangle i<j<k, and S every triangle (1,j,k). R is the entire ordered relation of label triples (a,b,c) such that y_a+y_b=y_c and either a≠b or mu_a≥2. Both orders of unequal summands are retained. The labels are strictly decreasing positive real numbers and the multiplicities are positive integers with total choose(n,2).")),
            Paragraph(Text("Set M_0=0 and M_q=sum_{r≤q} mu_r. The closed rank block [M_{q−1}+1,M_q] is allowed on ij exactly when M_q≥i(n−j+1) and M_{q−1}+1≤choose(n,2)−choose(j−i+1,2)+1. Its indicator is A_ij,q. This tests intersection, not inclusion or distinct-label rank. Every P coordinate obeys 0≤P_ij,q≤A_ij,q; every row sums to one and every label column sums to mu_q.")),
            Paragraph(Text("For H=Delta or S, PrunedProjection(y,mu,H) consists of such entire arrays P with an independent existential array T on H×R. Every block is nonnegative, sums to one, has the three marginals P_ij,P_jk,P_ik, and obeys T_tau,(a,b,c)≤A_ij,a A_jk,b A_ik,c. No equivalence with a P-only-mask system is assumed. The same entire P is compared; no global joint distribution, integrality, scalar replacement, P-free feasibility comparison, extension of a chosen spine T, or extra presolve is imposed.")),
            Paragraph(Text("For every triangle and each of the position pairs (1,2),(1,3),(2,3), let w be the remaining position. For every two labels alpha,beta, C is the complete set of labels gamma occurring in a member of R with all three masks allowed and coordinates r_u=alpha,r_v=beta,r_w=gamma. SingletonCuts is the conjunction P^u_alpha+P^v_beta≤1+sum_{gamma∈C}P^w_gamma for all these choices. Empty C contributes zero; masked coordinates and absent completions remain quantified. The Lean definition uses u<v and w distinct from both in Fin 3, which gives exactly those three pairs.")),
            Describe.Lean(DescribeId.Create("turnpike-pruned-singleton-claim"), DeclarationHandle.Create(Module + ".claim"),
                H("The unchanged universal all-cut claim"),
                StatementSource.FromAuthor(Disp(Equal(Typed(Q("claim"),Q("Prop")),Par(ClaimBody())))),
                AssessedProvenance.FromRepo(Source), Blocks(
                    Paragraph(Text("Admissible means n≥3, d≥1, strict decrease and positivity of y, positivity of every multiplicity, and total choose(n,2). Realizes(y,mu,x) requires a strictly increasing real ruler, a label for each of its entire set of interval differences, and exactly mu_q occurrences of each y_q. Existence of this ruler is an input premise; it does not assert that each fractional P is realized by a ruler."))), DescribeRole.Definition),
            Paragraph(Text("The certificate has n=9, d=20 and denominator 62. Its actual ruler is (0,5,6,9,11,19,20,21,22). In decreasing order y=(22,21,20,19,17,16,15,14,13,12,11,10,9,8,6,5,4,3,2,1) and mu=(1,1,1,1,1,2,2,2,2,1,3,2,2,1,2,2,1,2,3,4). All 36 actual differences are assigned labels by occurrence in the Lean source. Their counts are precisely mu, and the ruler is strictly increasing.")),
            Paragraph(Text("Complete P certificate: ij followed by q:z means P_ij,q=z/62. All omitted coordinates are exactly zero. Labels and vertices in this paragraph are one-based. 12 16:32 19:10 20:20; 13 15:38 16:12 19:12; 14 11:1 13:19 14:22 15:8 18:12; 15 8:2 9:8 10:4 11:10 12:31 13:7; 16 4:32 6:8 8:10 9:10 11:2; 17 3:32 5:10 6:16 8:4; 18 2:42 3:8 5:8 6:4; 19 1:62; 23 16:4 17:6 18:8 20:44; 24 12:1 14:8 15:9 17:11 18:13 19:11 20:9; 25 11:11 12:10 13:11 16:23 17:7; 26 7:8 8:32 9:10 11:10 12:2; 27 6:4 7:50 8:4 9:4; 28 4:18 6:40 7:4; 29 2:20 3:10 5:32; 34 15:1 18:22 19:19 20:20; 35 11:8 13:6 15:9 16:6 17:26 18:7; 36 9:32 11:12 12:6 13:12; 37 7:4 8:36 10:4 11:18; 38 6:6 7:50 8:6; 39 3:12 5:12 6:38; 45 13:4 14:6 15:4 16:11 18:2 19:17 20:18; 46 11:25 12:27 16:7 19:3; 47 9:8 10:12 11:23 12:8 13:11; 48 7:8 8:8 9:26 10:11 11:8 12:1; 49 4:12 6:8 8:22 9:19 11:1; 56 13:31 15:1 16:5 18:6 19:18 20:1; 57 11:7 12:25 15:16 18:8 19:6; 58 11:38 12:7 13:5 15:2 17:6 18:2 19:2; 59 9:7 10:31 11:10 12:4 13:8 14:2; 67 15:2 18:6 19:10 20:44; 68 12:2 14:10 15:6 19:34 20:10; 69 11:2 13:10 14:10 15:8 18:32; 78 16:6 17:6 18:6 19:4 20:40; 79 14:4 15:16 16:10 19:32; 89 15:4 16:8 19:8 20:42")),
            Paragraph(Text("Complete spine certificate: 1jk followed by a,b,c:z means mass z/62 at that ordered numerical relation triple. All omitted relation coordinates are exactly zero. The Lean raw table pads each block to twelve atoms with zero weights; weightedAtoms sums coincident atoms and eliminates the ambient relation sum before checking normalization and marginals. 123 16,20,15:32 19,17,15:2 19,18,16:8 20,16,15:4 20,17,16:4 20,20,19:12; 124 16,17,13:11 16,18,14:13 16,20,15:8 19,15,14:9 19,20,18:1 20,12,11:1 20,14,13:8 20,19,18:11; 125 16,13,8:2 16,16,12:23 16,17,13:7 19,11,9:8 19,12,10:1 19,13,11:1 20,11,10:3 20,12,11:9 20,13,12:8; 126 16,8,4:32 19,11,9:10 20,7,6:8 20,9,8:10 20,12,11:2; 127 16,7,3:32 19,7,5:6 19,8,6:4 20,6,5:4 20,7,6:12 20,9,8:4; 128 16,6,2:32 19,4,2:10 20,4,3:8 20,6,5:8 20,7,6:4; 129 16,5,1:32 19,3,1:10 20,2,1:20; 134 15,18,13:19 15,19,14:19 16,15,11:1 16,18,14:3 16,20,15:8 19,20,18:12; 135 15,15,10:4 15,16,11:1 15,17,12:26 15,18,13:7 16,13,8:2 16,15,11:5 16,16,12:5 19,11,9:8 19,13,11:4; 136 15,9,4:32 15,12,6:6 16,11,6:2 16,13,8:10 19,11,9:10 19,13,11:2; 137 15,8,3:32 15,11,5:6 16,11,6:12 19,7,5:4 19,8,6:4 19,10,8:4; 138 15,7,2:36 15,8,3:2 16,6,2:6 16,7,3:6 19,7,5:8 19,8,6:4; 139 15,6,1:38 16,5,1:12 19,3,1:12; 145 11,19,9:1 13,19,11:2 13,20,12:17 14,16,9:7 14,19,12:14 14,20,13:1 15,14,8:2 15,16,11:4 15,18,13:2 18,13,10:4 18,14,11:4 18,15,13:4; 146 11,19,9:1 13,12,4:17 13,19,11:2 14,11,4:15 14,16,9:7 15,12,6:8 18,11,8:10 18,12,9:2; 147 11,13,3:1 13,11,3:19 14,10,3:12 14,13,5:10 15,12,6:8 18,9,6:8 18,11,8:4; 148 11,12,2:1 13,10,2:11 13,11,3:8 14,9,2:22 15,7,2:8 18,8,5:8 18,9,6:4; 149 11,11,1:1 13,9,1:19 14,8,1:22 15,6,1:8 18,4,1:12; 156 8,19,6:2 9,15,4:1 9,18,6:6 9,20,8:1 10,19,8:4 11,19,9:10 12,13,4:31 13,16,8:5 13,19,11:2; 157 8,19,6:2 9,18,6:8 10,19,8:4 11,15,5:10 12,12,3:25 12,15,6:6 13,11,3:7; 158 8,19,6:2 9,17,5:6 9,18,6:2 10,13,2:4 11,12,2:7 11,13,3:1 11,15,5:2 12,11,2:31 13,11,3:7; 159 8,14,1:2 9,13,1:8 10,12,1:4 11,11,1:10 12,10,1:31 13,9,1:7; 167 4,20,3:32 6,20,5:8 8,19,6:10 9,18,6:6 9,20,8:4 11,15,5:2; 168 4,19,2:30 4,20,3:2 6,20,5:8 8,15,3:6 8,19,6:4 9,14,2:10 11,12,2:2; 169 4,18,1:32 6,15,1:8 8,14,1:10 9,13,1:10 11,11,1:2; 178 3,20,2:32 5,17,2:4 5,18,3:6 6,16,2:6 6,17,3:2 6,20,5:8 8,19,6:4; 179 3,19,1:32 5,16,1:10 6,15,1:16 8,14,1:4; 189 2,20,1:42 3,19,1:8 5,16,1:8 6,15,1:4")),
            Paragraph(Text("All P bounds, row sums and common column counts are retained. Each of the 28 spine blocks uses complete guarded R, has total numerator 62, all three exact marginals, and the product mask. OmegaMath.Combinatorics.Turnpike.PrunedSingletonCutData owns the integer assignment, completion candidate and complete triangle cover. PrunedSingletonCutPair01, PrunedSingletonCutPair02 and PrunedSingletonCutPair12 each own the 84 triangle shards for their coordinate pair and its coverage theorem. The consumed PrunedSingletonCutCertificate module aggregates these three pair theorems into the complete cut certificate. For the singleton cuts the certificate checks all 84 triangles, all three position pairs, and all 400 label pairs. A sum of two P numerators at most 62 satisfies its cut by nonnegativity. Otherwise a concrete candidate completion is obtained by exact integer addition or subtraction followed by lookup in y; the finite check proves that it lies in complete R with every mask allowed and that its remaining-coordinate numerator covers the excess. Membership in the explicitly defined complete completion set then proves the original cut. This sufficient proof does not replace that set by a guessed table or omit empty completions.")),
            Describe.Lean(DescribeId.Create("turnpike-pruned-singleton-result"), DeclarationHandle.Create(Module + ".result"),
                H("Refutation at the same entire assignment"),
                StatementSource.FromAuthor(Disp(new Formula.Not(Par(ClaimBody())))),
                AssessedProvenance.FromRepo(Source), Blocks(
                    Paragraph(Text("At triangle (2,3,4) take the distance subsets A={1,3,4}, B={1,2,3,6}, C={2,3,4,5,6,9,10}. Every complete guarded numerical relation triple whose first value is in A and second value is in B has outer value in C. Applying the existing Omega.Turnpike.coupling_separator to these three Boolean observations and a nonnegative normalized full block forces P23(A)+P34(B)≤1+P24(C). The certificate gives these masses as 58/62, 62/62 and 45/62, so the inequality fails by 13/62. Consequently no full T exists, including any independently chosen one.")),
                    Paragraph(Text("The displayed entire P therefore belongs to the pruned spine projection and satisfies every registered singleton cut, while it has no full lift. The generic union-bound separator is reused existing mathematics; the substantive instance is this realizable whole assignment and its all-cut spine certificate. This does not settle LP integrality, a minimal size or denominator, a universal family, or sufficiency of general subset transport inequalities."))), DescribeRole.Theorem))));

    private static Formula ClaimBody()
    {
        Formula ptype = new Formula.TypeArrow(App(Q("I"),X("n")),new Formula.TypeArrow(App(Q("Fin"),X("d")),Q("Real")));
        Formula full = App(Q("PrunedProjection"),X("y"),Mu,Q("Delta"));
        Formula spine = App(Q("PrunedProjection"),X("y"),Mu,Q("S"));
        Formula eq = All("P",ptype,Iff(App(Q("Member"),X("P"),full),
            And(App(Q("Member"),X("P"),spine),App(Q("SingletonCuts"),X("y"),Mu,X("P")))));
        Formula realizes = Seq(Exists,Sp,Typed(X("x"),new Formula.TypeArrow(App(Q("Fin"),X("n")),Q("Real"))),Comma,Sp,
            App(Q("Realizes"),X("y"),Mu,X("x")));
        Formula body = Imp(App(Q("Admissible"),X("n"),X("d"),X("y"),Mu),Imp(realizes,eq));
        return All("n",Q("Nat"),All("d",Q("Nat"),All("y",new Formula.TypeArrow(App(Q("Fin"),X("d")),Q("Real")),
            All("mu",new Formula.TypeArrow(App(Q("Fin"),X("d")),Q("Nat")),body))));
    }
    private static Formula App(Formula f,params Formula[] args) => new Formula.Apply(f,[..args]);
    private static Formula Par(Formula x) => Seq(Left,Open,x,Right,Close);
    private static Formula Typed(Formula a,Formula b) => Par(Seq(a,Colon,Sp,b));
    private static Formula All(string v,Formula t,Formula b) => Seq(Forall,Sp,Typed(X(v),t),Comma,Sp,Par(b));
    private static Formula And(Formula a,Formula b) => new Formula.Logic(Par(a),FormulaLogicOperator.And,Par(b));
    private static Formula Imp(Formula a,Formula b) => new Formula.Logic(Par(a),FormulaLogicOperator.Implies,Par(b));
    private static Formula Iff(Formula a,Formula b) => And(Imp(a,b),Imp(b,a));
    private static Formula X(string name) => name == "mu" ? Mu : F.Id(name);
    private static Formula Q(string name) => Seq(Operatorname,Grp(F.Id(name)));
}
